import base64
import os
from typing import AsyncIterator, Dict, List, Optional, Type
from urllib.parse import quote, urlencode

import aiohttp
import orjson
import structlog
from aiohttp import ClientTimeout, ClientWSTimeout
from pydantic import Field, model_validator

from rasa.core.channels.voice_stream.audio_bytes import (
    L16_16KHZ,
    L16_24KHZ,
    L16_48KHZ,
    MULAW_8KHZ,
    AudioFormat,
    RasaAudioBytes,
)
from rasa.core.channels.voice_stream.tts._client_session import (
    create_ssl_client_session,
)
from rasa.core.channels.voice_stream.tts.config import StreamingConfig
from rasa.core.channels.voice_stream.tts.tts_engine import (
    TTSConfigError,
    TTSEngine,
    TTSEngineConfig,
    TTSError,
    TTSStreamEvent,
    TTSWordTimestamps,
)
from rasa.shared.constants import ELEVENLABS_API_KEY_ENV_VAR
from rasa.shared.exceptions import ConnectionException
from rasa.tracing import voice as voice_tracing

structlogger = structlog.get_logger()

ELEVENLABS_TTS_ENDPOINT = "wss://api.elevenlabs.io/v1/text-to-speech"
ELEVENLABS_DEFAULT_MODEL_ID = "eleven_multilingual_v2"


class ElevenLabsTTSConfig(TTSEngineConfig):
    """Configuration for ElevenLabs speech synthesis."""

    endpoint: str = ELEVENLABS_TTS_ENDPOINT
    model_id: str = ELEVENLABS_DEFAULT_MODEL_ID
    stability: Optional[float] = Field(default=None, ge=0, le=1)
    similarity_boost: Optional[float] = Field(default=None, ge=0, le=1)

    @model_validator(mode="after")
    def _validate_voice_ids(self) -> "ElevenLabsTTSConfig":
        if self.language_map is None:
            return self

        missing_voice_languages = [
            language
            for language, entry in self.language_map.items()
            if entry.voice is None or not entry.voice.strip()
        ]
        if missing_voice_languages:
            language_list = ", ".join(sorted(missing_voice_languages))
            raise ValueError(
                "ElevenLabs TTS requires a voice ID in each language_map entry. "
                f"Missing voice ID for: {language_list}."
            )
        return self

    def validate_language_map_keys(
        self,
        rasa_language: Optional[str],
        additional_languages: Optional[List[str]] = None,
    ) -> None:
        if not self.language_map:
            raise TTSConfigError(
                "ElevenLabs TTS requires a voice ID. Configure 'voice' in "
                "each 'language_map' entry."
            )
        super().validate_language_map_keys(rasa_language, additional_languages)


class ElevenLabsTTS(TTSEngine[ElevenLabsTTSConfig]):
    """Stream text to ElevenLabs and yield audio with word-level timings."""

    required_env_vars = (ELEVENLABS_API_KEY_ENV_VAR,)
    streaming_input = True

    def __init__(
        self,
        rasa_language: str,
        format: AudioFormat,
        config: Optional[ElevenLabsTTSConfig] = None,
        additional_languages: Optional[List[str]] = None,
    ) -> None:
        super().__init__(rasa_language, format, config, additional_languages)
        self.session: Optional[aiohttp.ClientSession] = None
        self.ws: Optional[aiohttp.ClientWebSocketResponse] = None
        self._pending_text = ""
        self._text_done = False
        self._interrupted = False

    @classmethod
    def name(cls) -> str:
        """Return the name identifier for this TTS engine."""
        return "elevenlabs"

    def get_websocket_url(self) -> str:
        """Build the streaming URL for the active voice and model."""
        voice_id = self.current_language_config.voice
        if not voice_id:
            raise TTSError(
                "ElevenLabs TTS requires a voice ID in the language_map configuration"
            )

        model_id = self.current_language_config.model or self.config.model_id
        if model_id.startswith(("eleven_v3", "eleven_v4")):
            raise TTSError(
                "The ElevenLabs Text-to-Speech WebSocket does not support "
                "Eleven v3 or v4 models."
            )

        query_params = {
            "model_id": model_id,
            "output_format": self._output_format(),
            "sync_alignment": "true",
            "inactivity_timeout": "180",
        }
        if (
            self.current_language_config.engine_language_key
            and model_id != ELEVENLABS_DEFAULT_MODEL_ID
        ):
            query_params["language_code"] = (
                self.current_language_config.engine_language_key
            )

        endpoint = self.config.endpoint.rstrip("/")
        return (
            f"{endpoint}/{quote(voice_id, safe='')}/stream-input?"
            f"{urlencode(query_params)}"
        )

    @voice_tracing.traced_tts_connect
    async def connect(self, config: Optional[ElevenLabsTTSConfig] = None) -> None:
        """Open and initialize the ElevenLabs single-context WebSocket."""
        if self.ws is not None and not self.ws.closed:
            return
        if self.session is None or self.session.closed:
            self.session = create_ssl_client_session(
                ClientTimeout(total=self.config.timeout)
            )

        websocket: Optional[aiohttp.ClientWebSocketResponse] = None
        try:
            websocket = await self.session.ws_connect(
                self.get_websocket_url(),
                headers={"xi-api-key": os.environ[ELEVENLABS_API_KEY_ENV_VAR]},
                timeout=ClientWSTimeout(ws_close=float(self.config.timeout)),
            )
            initialization: Dict[str, object] = {"text": " "}
            voice_settings: Dict[str, float] = {}
            if self.config.stability is not None:
                voice_settings["stability"] = self.config.stability
            if self.config.similarity_boost is not None:
                voice_settings["similarity_boost"] = self.config.similarity_boost
            if voice_settings:
                initialization["voice_settings"] = voice_settings
            await websocket.send_json(initialization)
            self.ws = websocket
        except (aiohttp.ClientError, asyncio.TimeoutError) as error:
            if websocket is not None and not websocket.closed:
                await websocket.close()
            if isinstance(error, aiohttp.ClientResponseError):
                structlogger.error(
                    "elevenlabs.tts.connection_failed",
                    status_code=error.status,
                )
                if error.status == 401:
                    raise ConnectionException(
                        "ElevenLabs authentication failed; check ELEVENLABS_API_KEY."
                    ) from error
            else:
                structlogger.error(
                    "elevenlabs.tts.connection_failed",
                    error_type=type(error).__name__,
                )
            raise ConnectionException("Connection to ElevenLabs TTS failed.") from error

    @voice_tracing.traced_tts_disconnect
    async def close_connection(self) -> None:
        """Close the WebSocket and its HTTP session."""
        websocket = self.ws
        self.ws = None
        if websocket is not None and not websocket.closed:
            await websocket.close()
        if self.session is not None and not self.session.closed:
            await self.session.close()
        self.session = None

    async def prepare_response(
        self, streaming_config: Optional[StreamingConfig] = None
    ) -> None:
        self._pending_text = ""
        self._text_done = False
        self._interrupted = False
        if self.ws is None or self.ws.closed:
            await self.connect()

    async def send_text_chunk(self, text: str) -> None:
        """Send completed words as text arrives from the language model."""
        async with self._get_engine_lock():
            if self._text_done or self._interrupted:
                raise TTSError("ElevenLabs TTS response no longer accepts text")

            websocket = self.ws
            if websocket is None or websocket.closed:
                raise TTSError("ElevenLabs TTS WebSocket is not connected")

            self._pending_text += text
            split_at = max(
                (
                    index
                    for index, character in enumerate(self._pending_text)
                    if character.isspace()
                ),
                default=-1,
            )
            if split_at < 0:
                return

            complete_text = self._pending_text[: split_at + 1]
            self._pending_text = self._pending_text[split_at + 1 :]
            complete_text = complete_text.rstrip() + " "
            if complete_text.strip():
                await websocket.send_json({"text": complete_text})

    async def signal_text_done(self) -> None:
        """Flush remaining text and mark the current response complete."""
        async with self._get_engine_lock():
            if self._text_done or self._interrupted:
                return
            websocket = self.ws
            if websocket is None or websocket.closed:
                raise TTSError("ElevenLabs TTS WebSocket is not connected")

            remaining_text = self._pending_text.rstrip()
            self._pending_text = ""
            if remaining_text:
                await websocket.send_json({"text": f"{remaining_text} "})
            await websocket.send_json({"text": ""})
            self._text_done = True

    async def signal_interrupt(self) -> None:
        """Close the single context so buffered provider audio is discarded."""
        async with self._get_engine_lock():
            self._interrupted = True
            self._pending_text = ""
            websocket = self.ws
            self.ws = None
            if websocket is not None and not websocket.closed:
                await websocket.close()

    async def stream_audio(self) -> AsyncIterator[RasaAudioBytes]:
        async for event in self.stream_audio_events():
            if isinstance(event, RasaAudioBytes):
                yield event

    async def synthesize(
        self, text: str, config: Optional[ElevenLabsTTSConfig] = None
    ) -> AsyncIterator[RasaAudioBytes]:
        response = await self.start_response()
        await response.write(text)
        await response.finish()
        async for audio_chunk in response:
            yield audio_chunk

    async def stream_audio_events(self) -> AsyncIterator[TTSStreamEvent]:
        """Yield provider audio and alignment until the response is finalized."""
        if self._interrupted:
            return
        websocket = self.ws
        if websocket is None or websocket.closed:
            raise TTSError("ElevenLabs TTS WebSocket is not connected")

        received_audio_seconds = 0.0
        try:
            async for message in websocket:
                if message.type in (
                    aiohttp.WSMsgType.CLOSE,
                    aiohttp.WSMsgType.CLOSED,
                    aiohttp.WSMsgType.CLOSING,
                ):
                    break
                if message.type is aiohttp.WSMsgType.ERROR:
                    raise TTSError("ElevenLabs TTS WebSocket returned an error")
                if message.type is not aiohttp.WSMsgType.TEXT:
                    continue

                try:
                    data = orjson.loads(message.data)
                except orjson.JSONDecodeError as error:
                    raise TTSError(
                        "ElevenLabs returned an invalid WebSocket event"
                    ) from error
                if not isinstance(data, dict):
                    continue
                if data.get("error") == "voice_id_does_not_exist":
                    structlogger.error(
                        "elevenlabs.tts.provider_error",
                        error_code="voice_id_does_not_exist",
                    )
                    raise TTSError(
                        "The ElevenLabs voice is unavailable to this API key or model."
                    )
                if data.get("error"):
                    raise TTSError("ElevenLabs TTS returned an error")

                timestamps = _word_timestamps(data.get("alignment"))
                if timestamps is not None and timestamps.timestamps:
                    yield timestamps.shifted(received_audio_seconds)

                audio_base64 = data.get("audio")
                if isinstance(audio_base64, str) and audio_base64:
                    try:
                        audio = base64.b64decode(audio_base64, validate=True)
                    except ValueError as error:
                        raise TTSError(
                            "ElevenLabs returned invalid audio data"
                        ) from error
                    if audio:
                        audio_chunk = RasaAudioBytes(audio, format=self.audio_format)
                        received_audio_seconds += audio_chunk.full_seconds()
                        yield audio_chunk

                if data.get("is_final", data.get("isFinal")) is True:
                    if self.ws is websocket:
                        self.ws = None
                    if not websocket.closed:
                        await websocket.close()
                    return
        except asyncio.CancelledError:
            raise
        except (aiohttp.ClientError, asyncio.TimeoutError) as error:
            if self._interrupted:
                return
            structlogger.error(
                "elevenlabs.tts.stream_failed",
                error_type=type(error).__name__,
            )
            raise TTSError("ElevenLabs TTS stream failed") from error

        if not self._interrupted:
            raise TTSError("ElevenLabs TTS WebSocket closed before the response ended")

    async def set_language(self, rasa_language: str) -> bool:
        changed = await super().set_language(rasa_language)
        if changed:
            await self._reconnect_with_lock()
        return changed

    def _output_format(self) -> str:
        formats = {
            MULAW_8KHZ: "ulaw_8000",
            L16_16KHZ: "pcm_16000",
            L16_24KHZ: "pcm_24000",
            L16_48KHZ: "pcm_48000",
        }
        output_format = formats.get(self.audio_format)
        if output_format is None:
            raise TTSError(f"Unsupported ElevenLabs audio format: {self.audio_format}")
        return output_format

    def engine_bytes_to_rasa_audio_bytes(self, chunk: bytes) -> RasaAudioBytes:
        return RasaAudioBytes(chunk, format=self.audio_format)

    @staticmethod
    def get_default_config(rasa_language: str) -> ElevenLabsTTSConfig:
        return ElevenLabsTTSConfig()

    @classmethod
    def from_config_dict(
        cls: Type["ElevenLabsTTS"],
        config: Dict,
        format: AudioFormat,
        rasa_language: str,
        additional_languages: Optional[List[str]] = None,
    ) -> "ElevenLabsTTS":
        return cls(
            rasa_language=rasa_language,
            format=format,
            config=ElevenLabsTTSConfig.model_validate(config),
            additional_languages=additional_languages,
        )


def _word_timestamps(alignment: object) -> Optional[TTSWordTimestamps]:
    if not isinstance(alignment, dict):
        return None

    characters = alignment.get("chars")
    starts = alignment.get("char_start_times_ms")
    durations = alignment.get("char_durations_ms")
    if not (
        isinstance(characters, list)
        and isinstance(starts, list)
        and isinstance(durations, list)
        and len(characters) == len(starts) == len(durations)
    ):
        return None

    if any(
        isinstance(value, bool) or not isinstance(value, (int, float))
        for value in [*starts, *durations]
    ):
        return None

    word_starts = [value / 1000 for value in starts]
    word_ends = [
        (start + duration) / 1000 for start, duration in zip(starts, durations)
    ]
    return _characters_to_word_timestamps(characters, word_starts, word_ends)


def _characters_to_word_timestamps(
    characters: List[object], starts: List[object], ends: List[object]
) -> Optional[TTSWordTimestamps]:
    if not len(characters) == len(starts) == len(ends):
        return None

    words: List[str] = []
    word_starts: List[object] = []
    word_ends: List[object] = []
    current_word: List[str] = []
    current_start: object = 0
    current_end: object = 0

    for character, start, end in zip(characters, starts, ends):
        if not isinstance(character, str):
            return None
        if character.isspace():
            if current_word:
                words.append("".join(current_word))
                word_starts.append(current_start)
                word_ends.append(current_end)
                current_word = []
            continue
        if not current_word:
            current_start = start
        current_word.append(character)
        current_end = end

    if current_word:
        words.append("".join(current_word))
        word_starts.append(current_start)
        word_ends.append(current_end)

    return TTSWordTimestamps.parse(words, word_starts, word_ends)
